// Cheap sentiment fallback: scan for positive/negative cues + intensity marks.
function _sentiment(text){
  const t=(text||'').toLowerCase();
  let v=0,e=0.5,hits=0;
  const POS=/good|nice|love|happy|bright|warm|soft|light|hope|joy|dob|kras|jasn|tepl|svetl/;
  const NEG=/bad|dark|cold|hard|hurt|cry|loss|alone|zl|temn|stud|tvrd|sam|plak/;
  const HI=/storm|fire|fast|loud|burn|rush|búr|bur|rýchl|rychl|hlas|oheň|ohen/;
  const LO=/slow|soft|sleep|still|quiet|pomal|tich|spán|span/;
  if(POS.test(t)){v+=0.5;hits++;} if(NEG.test(t)){v-=0.5;hits++;}
  if(HI.test(t)){e+=0.3;hits++;} if(LO.test(t)){e-=0.3;hits++;}
  // exclamation / caps → more energy
  if(/!/.test(text||'')) e+=0.15;
  return {v:Math.max(-1,Math.min(1,v)), e:Math.max(0,Math.min(1,e)), hits};
}
// Map analysed {v,e} to concrete musical parameters.
function _moodParams(text){
  let v=0,e=0.5,matched=false;
  for(const [re,p] of _MOOD_LEX){ if(re.test(text)){ v=p.v; e=p.e; matched=true; break; } }
  if(!matched){ const s=_sentiment(text); v=s.v; e=s.e; }
  // tempo: low energy ~60, high energy ~140
  const tempo=Math.round(60+e*80);
  // scale: positive valence → major-ish, negative → minor/darker
  // intervals are semitone offsets from the tonic
  const major=[0,2,4,5,7,9,11], minor=[0,2,3,5,7,8,10];
  const harmMinor=[0,2,3,5,7,8,11], lydian=[0,2,4,6,7,9,11];
  let scale; if(v>=0.5) scale=(e>0.7?lydian:major); else if(v>=0) scale=major; else if(v>-0.6) scale=minor; else scale=harmMinor;
  // tonic: brighter moods higher, darker lower (C=0 ... pick a root pitch class)
  const root = v>=0.3 ? 0 /*C*/ : v>=-0.3 ? 7 /*G*/ : 2 /*D*/;
  // density: energetic = shorter notes, more of them
  const beatStep = e>0.8?0.5 : e>0.55?1 : e>0.3?1.5 : 2;
  return {v,e,tempo,scale,root,beatStep,matched};
}
